def _rich_block(value):
    value = value or ''
    value = str(value).strip()
    if not value:
        return ''
    if value.startswith('<'):
        return value
    return f'<p>{escape(value)}</p>'


def _plain_text(value):
    value = value or ''
    return re.sub(r'<[^>]+>', '', str(value)).strip()


def _field_value(value):
    return str(value) if value else ''


def _unique_slug(Service, value):
    base_slug = slugify(value)[:220] or 'service'
    slug = base_slug
    counter = 2
    while Service.objects.filter(slug=slug).exists():
        suffix = f'-{counter}'
        slug = f'{base_slug[:255 - len(suffix)]}{suffix}'
        counter += 1
    return slug


def _infer_group(title, name):
    text = f'{title} {name}'.lower()
    if 'design' in text and 'graphic' not in text:
        return 'web-designing'
    if 'portal' in text:
        return 'web-portal-development'
    if 'mobile' in text or 'android' in text or 'ios' in text:
        return 'mobile-app-development'
    if 'tally' in text and ('cloud' in text or 'remote' in text):
        return 'tally-on-cloud'
    if 'tally' in text or 'tdl' in text or 'integration' in text:
        return 'tally-customization-integration'
    if 'digital' in text or 'seo' in text or 'marketing' in text:
        return 'digital-marketing'
    if 'graphic' in text or 'logo' in text or 'brochure' in text:
        return 'graphics-designing'
    if 'cloud' in text or 'hosting' in text or 'server' in text:
        return 'cloud-services'
    if 'module' in text or 'approval' in text or 'barcode' in text or 'e-commerce' in text or 'ecommerce' in text:
        return 'tally-vertical-solutions'
    return 'website-development'


def _is_module_service(title, name):
    text = f'{title} {name}'.lower()
    keywords = ('module', 'approval', 'barcode', 'e-commerce', 'ecommerce', 'garments', 'workflow')
    return any(keyword in text for keyword in keywords)


def _copy_service(Service, fallback_user, old_service, group, sort_order, show_on_landing=False, show_on_module_page=False):
    title = getattr(old_service, 'title', '') or ''
