def copy_legacy_services(apps, schema_editor):
    User = apps.get_model('auth', 'User')
    Service = apps.get_model('web2', 'Service')
    WebDevModel = apps.get_model('web2', 'WebDevModel')
    WebDesignModel = apps.get_model('web2', 'Web_DesignModel')
    WebPortalDev = apps.get_model('web2', 'Web_Portal_Dev')
    MobileAppModel = apps.get_model('web2', 'MobileAppModel')
    TallyCustomization = apps.get_model('web2', 'Tally_Customization')
    TallyVertical = apps.get_model('web2', 'Tally_VerticalModel')
    TallyCloud = apps.get_model('web2', 'Tally_CloudModel')
    DigitalMarketing = apps.get_model('web2', 'Digital_Mkt_Model')
    Graphics = apps.get_model('web2', 'Graphics_Model')
    Cloud = apps.get_model('web2', 'CloudModel')
    LandingService = apps.get_model('web2', 'Lan_ServicesModel')

    fallback_user = (
        User.objects.filter(username='content_admin').first()
        or User.objects.filter(username='admin').first()
        or User.objects.first()
    )
    if fallback_user is None:
        fallback_user = User.objects.create(username='content_admin', email='info@initiatorsolutions.com')

    sources = [
        (WebDevModel, 'website-development', False, False),
        (WebDesignModel, 'web-designing', False, False),
        (WebPortalDev, 'web-portal-development', False, False),
        (MobileAppModel, 'mobile-app-development', False, False),
        (TallyCustomization, 'tally-customization-integration', False, False),
        (TallyVertical, 'tally-vertical-solutions', False, True),
        (TallyCloud, 'tally-on-cloud', False, False),
        (DigitalMarketing, 'digital-marketing', False, False),
        (Graphics, 'graphics-designing', False, False),
        (Cloud, 'cloud-services', False, False),
    ]

    sort_order = 10
    for model, group, show_on_landing, show_on_module_page in sources:
        for old_service in model.objects.all().order_by('id'):
            _copy_service(Service, fallback_user, old_service, group, sort_order, show_on_landing, show_on_module_page)
            sort_order += 10

    for old_service in LandingService.objects.all().order_by('id'):
        title = getattr(old_service, 'title', '') or ''
        name = getattr(old_service, 'name', '') or ''
        group = _infer_group(title, name)
        _copy_service(
            Service,
            fallback_user,
            old_service,
            group,
            sort_order,
            show_on_landing=True,
            show_on_module_page=_is_module_service(title, name),
        )
        sort_order += 10


